def resolve(path, cwd, links):
    # Start with cwd if path is relative
    if not path.startswith('/'):
        if not cwd.startswith('/'):
            return None
        current = cwd
    else:
        current = '/'
        path = path[1:]  # Remove leading slash for processing

    # Split path into components and filter empty ones
    components = [c for c in path.split('/') if c]

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '.' or comp == '':
            # Skip empty and '.'
            i += 1
            continue
        elif comp == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue
        else:
            # Append the component
            if current == '/':
                candidate = '/' + comp
            else:
                candidate = current + '/' + comp

            # Check if this is a symlink
            if candidate in links:
                if link_count >= max_links:
                    return None
                link_count += 1

                # Resolve the link target
                target = links[candidate]

                # The target is relative to the directory containing the link
                if target.startswith('/'):
                    # Absolute target
                    current = '/'
                    target_path = target[1:]
                else:
                    # Relative target - relative to the directory containing the link
                    if candidate == '/':
                        link_dir = '/'
                    else:
                        link_dir = candidate.rsplit('/', 1)[0]
                        if link_dir == '':
                            link_dir = '/'
                    current = link_dir
                    target_path = target

                # Split target into components
                target_comps = [c for c in target_path.split('/') if c]

                # Replace current component with target components
                components = components[:i] + target_comps + components[i+1:]
                # Don't increment i; process the target components
                continue
            else:
                # Not a symlink, just move to this path
                current = candidate
                i += 1

    # Remove trailing slash (except for root)
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

